<?php require_once "../config/database.php";require_once "../includes/auth.php";require_role("student");$id=(int)($_GET["id"]??0);$s=$conn->prepare("SELECT * FROM complaints WHERE id=? AND user_id=? AND status='Resolved'");$s->bind_param("ii",$id,$_SESSION["user_id"]);$s->execute();$c=$s->get_result()->fetch_assoc();if(!$c)die("Complaint not found.");$msg="";
