include "../includes/header.php";?><div class="form"><h2>Feedback — SC-<?=str_pad($id,4,"0",STR_PAD_LEFT)?></h2><?php if($msg):?><div class="alert ok"><?=e($msg)?></div><?php endif;?><form method="post"><div class="field"><label>Rating (1–5)</label><select name="rating" required><option value="">Select</option><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option></select></div><div class="field"><label>Comment</label><textarea name="comment"></textarea></div><button class="btn">Submit Feedback</button></form></div><?php include "../includes/footer.php";?>